function evaluate(p,r){const hold=reason=>({status:"HOLD",reason,authority:false});if(!r||r.head!==p.head||r.tree!==p.tree||r.toolchain!==p.toolchain||r.authority!==false)return hold("identity");const workload=p.workloads.find(w=>w.part===r.part);if(!workload||!["warm","cold"].includes(r.regime)||typeof r.hostFingerprint!=="string"||!r.hostFingerprint.trim()||typeof r.environmentFingerprint!=="string"||!r.environmentFingerprint.trim())return hold("conditions");if(!Array.isArray(r.trials)||r.trials.length!==6)return hold("three paired repetitions");let seen=new Set(),groups={};for(const t of r.trials){if(!Number.isInteger(t.pair)||t.pair<1||t.pair>3||!["cargo-default","cargo-2"].includes(t.variant)||t.hostFingerprint!==r.hostFingerprint||t.environmentFingerprint!==r.environmentFingerprint||t.regime!==r.regime||t.head!==p.head||t.exit!==0||t.ignored!==0||t.failed!==0||t.retry!==0||!Number.isFinite(t.wallSeconds)||t.wallSeconds<=0||!Number.isFinite(t.peakRssMiB)||t.peakRssMiB<=0||typeof t.logSha256!=="string"||!/^[a-f0-9]{64}$/.test(t.logSha256)||!Array.isArray(t.executed)||JSON.stringify([...t.executed].sort())!==JSON.stringify(workload.cases))return hold("trial custody or execution");const key=t.pair+":"+t.variant;if(seen.has(key))return hold("duplicate trial");seen.add(key);(groups[t.pair]??=[]).push(t)}
const ratios=[];for(let n=1;n<=3;n++){let g=groups[n];if(!g||g.length!==2||JSON.stringify(g.map(t=>t.variant))!==JSON.stringify(p.pilotOrder[n-1]))return hold("order or missing pair");let a=g.find(t=>t.variant==="cargo-default"),b=g.find(t=>t.variant==="cargo-2");ratios.push({pair:n,control:a.wallSeconds,tuned:b.wallSeconds,ratio:b.wallSeconds/a.wallSeconds,rssRatio:b.peakRssMiB/a.peakRssMiB})}
let sorted=ratios.map(x=>x.ratio).sort((a,b)=>a-b);return {status:"COMPARABLE_PILOT_ONLY",ratios,medianPairedWallRatio:sorted[1],medianPairedReductionPct:100*(1-sorted[1]),authority:false,note:"No adoption decision; wider workloads, proof/receipt parity, independent reproduction and native hosts remain."}}
function test(p,s,cases){return cases.map(([name,mut,want])=>{const x=JSON.parse(JSON.stringify(s));mut(x);const result=evaluate(p,x);if(result.status!==want||result.authority!==false)throw Error(name);return {name,status:result.status}})}
const cases=[["positive",x=>{},"COMPARABLE_PILOT_ONLY"],["foreign tree",x=>x.tree="bad","HOLD"],["missing test",x=>x.trials[0].executed.pop(),"HOLD"],["duplicate test",x=>x.trials[0].executed[1]=x.trials[0].executed[0],"HOLD"],["ignored test",x=>x.trials[0].ignored=1,"HOLD"],["failed exit",x=>x.trials[0].exit=1,"HOLD"],["retry masking",x=>x.trials[0].retry=1,"HOLD"],["different host",x=>x.trials[0].hostFingerprint="other","HOLD"],["different environment",x=>x.trials[0].environmentFingerprint="other","HOLD"],["different cache regime",x=>x.trials[0].regime="cold","HOLD"],["missing pair",x=>x.trials.pop(),"HOLD"],["reordered trial",x=>[x.trials[0],x.trials[1]]=[x.trials[1],x.trials[0]],"HOLD"],["missing log digest",x=>x.trials[0].logSha256="","HOLD"],["no RSS",x=>x.trials[0].peakRssMiB=0,"HOLD"]];
console.log(JSON.stringify({plan,receiptTemplate:process.argv[2]?undefined:synthetic,tests:test(plan,synthetic,cases),measurement:process.argv[2]?evaluate(plan,JSON.parse(readFileSync(process.argv[2],"utf8"))):"NOT RUN; synthetic template only"},null,2));
